import { createRoot } from 'react-dom/client';
import './index.css';
import * as React from 'react';
import { useRef, useEffect } from 'react';
import { createRoot as reactCreateRoot } from 'react-dom/client';

import { FileManagerComponent, Inject, NavigationPane, DetailsView, Toolbar } from '@syncfusion/ej2-react-filemanager';
import { DropDownButtonComponent } from '@syncfusion/ej2-react-splitbuttons';

const hostUrl = 'https://physical-service.syncfusion.com/';
const actionItems = [
    { text: 'Open', iconCss: 'e-icons e-folder-open' },
    { text: 'Download', iconCss: 'e-icons e-download' },
    { text: 'Refresh', iconCss: 'e-icons e-refresh' },
    { text: 'Delete', iconCss: 'e-icons e-trash' },
];
const Template = () => {
    const fmRef = useRef(null);
    const formatSize = (bytes) => {
        if (!bytes)
            return '0 B';
        const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
        let i = 0;
        let value = bytes;
        while (value >= 1024 && i < sizes.length - 1) {
            value /= 1024;
            i++;
        }
        return `${value.toFixed(1)} ${sizes[i]}`;
    };
    const getBackgroundCss = (item) => {
        const NamedFileBackgrounds = {
            'Adam.png': 'background-Adam',
            'Andrew.png': 'background-Andrew',
            'Ellie.png': 'background-Ellie',
            'Jameson.png': 'background-Jameson',
            'John.png': 'background-John',
            'Josie.png': 'background-Josie',
            'Apple pie.png': 'background-Applepie',
            'Bread.png': 'background-Bread',
            'Doughnut.png': 'background-Doughnut',
            'Nuggets.png': 'background-Nuggets',
            'Sugar cookie.png': 'background-Sugarcookie',
            'bird.jpg': 'background-bird',
            'sea.jpg': 'background-sea',
            'seaview.jpg': 'background-seaview',
            'snow.jpg': 'background-snow',
            'snowfall.jpg': 'background-snowfall'
        };
        const ExtensionBackgrounds = {
            jpg: 'background-jpg',
            jpeg: 'background-jpg',
            png: 'background-png',
            pptx: 'background-pptx',
            pdf: 'background-pdf',
            mp4: 'background-video',
            mp3: 'background-audio',
            docx: 'background-doc',
            txt: 'background-txt',
            xlsx: 'background-xlsx',
            zip: 'background-zip',
        };
        if (!item.isFile)
            return 'file-icon background-folder';
        if (NamedFileBackgrounds[item.name])
            return `file-icon ${NamedFileBackgrounds[item.name]}`;
        const ext = (item.name.split('.').pop() || '').toLowerCase();
        return `file-icon ${ExtensionBackgrounds[ext] || 'background-default'}`;
    };
    const getIconsForFolders = (item) => {
        const iconMap = {
            Files: 'e-folder',
            Documents: 'e-file-document',
            Downloads: 'e-download',
            Pictures: 'e-thumbnail',
            Music: 'e-file-format',
            Videos: 'e-video',
            Employees: 'e-export-png',
            Food: 'e-export-png',
            Nature: 'e-export-png'
        };
        return iconMap[item.name] || 'e-folder';
    };
    const getFileIconCssClass = (item) => {
        if (!item.isFile)
            return '';
        const extensionMap = {
            jpg: 'image',
            jpeg: 'image',
            png: 'image',
            gif: 'image',
            mp3: 'music',
            wav: 'music',
            mp4: 'video',
            avi: 'video',
            doc: 'doc',
            docx: 'docx',
            ppt: 'pptx',
            pptx: 'pptx',
            xls: 'xlsx',
            xlsx: 'xlsx',
            txt: 'txt',
            js: 'js',
            css: 'css',
            html: 'html',
            exe: 'exe',
            msi: 'msi',
            php: 'php',
            xml: 'xml',
            zip: 'zip',
            rar: 'rar',
            pdf: 'pdf'
        };
        const extension = (item.name.split('.').pop() || '').toLowerCase();
        const iconType = extensionMap[extension] || 'unknown';
        return `e-list-icon e-fe-${iconType}`;
    };
    const onActionSelect = (action, item) => {
        if (!fmRef.current)
            return;
        switch (action) {
            case 'Open':
                fmRef.current.openFile(item.name);
                break;
            case 'Download':
                fmRef.current.downloadFiles([item.name]);
                break;
            case 'Refresh':
                fmRef.current.refreshFiles();
                break;
            case 'Delete':
                fmRef.current.deleteFiles([item.name]);
                break;
            default:
                break;
        }
    };
    // Render DropDownButtonComponent (React) into each action host
    const renderDDBIntoHost = (hostEl) => {
        const fileName = hostEl.getAttribute('data-name') || '';
        const isFile = (hostEl.getAttribute('data-isfile') || 'false') === 'true';
        const items = isFile ? actionItems.filter(i => i.text !== 'Open') : actionItems;
        const onSelect = (args) => {
            const action = args?.item?.text || '';
            onActionSelect(action, { name: fileName, isFile });
        };
        if (!hostEl.hasAttribute('data-ddb-initialized')) {
            const root = reactCreateRoot(hostEl);
            root.render(<DropDownButtonComponent items={items} cssClass="e-caret-hide filemanager-dropdown-button" iconCss="e-icons e-more-vertical-1" select={onSelect}/>);
            hostEl.setAttribute('data-ddb-initialized', 'true');
        }
    };
    const menuOpen = (args) => {
        args.cancel = true;
    };
    const fileLoad = (args) => {
        const validModules = ['DetailsView', 'LargeIconsView'];
        if (validModules.indexOf(args.module) !== -1) {
            setTimeout(() => {
                const actionBtn = args.element.querySelector('.action-ddb');
                if (actionBtn && !actionBtn.hasAttribute('data-ddb-initialized')) {
                    renderDDBIntoHost(actionBtn);
                }
            }, 10);
        }
    };
    const detailsViewSettings = {
        columns: [
            {
                field: 'name',
                headerText: 'Name',
                template: (item) => (<div>{item.name}</div>)
            },
            {
                field: 'size',
                headerText: 'Size',
                template: (item) => (<div>{item.isFile ? formatSize(item.size) : '-'}</div>)
            },
            {
                field: '_fm_modified',
                headerText: 'DateModified',
                format: 'MM/dd/yyyy hh:mm a'
            },
            {
                headerText: 'Actions',
                template: (item) => (<div className="action-ddb" data-name={item.name} data-isfile={item.isFile}/>)
            }
        ]
    };
    const largeIconsTemplate = (item) => {
        const formattedDate = item.dateCreated
            ? new Date(item.dateCreated).toLocaleDateString('en-US', {
                year: 'numeric',
                month: 'long',
                day: 'numeric',
            })
            : '';
        const iconClass = getFileIconCssClass(item);
        const backgroundClass = getBackgroundCss(item);
        return (<div className="custom-icon-card">
        <div className="file-header">
          <div className="left-info">
            {item.isFile && <div className={iconClass}></div>}
            <div className="file-name" title={item.name}>
              {item.name}
            </div>
          </div>
          <div className="action-ddb" data-name={item.name} data-isfile={item.isFile}></div>
        </div>
        <div className={backgroundClass} title={item.name}></div>
        <div className="file-formattedDate">Created on {formattedDate}</div>
      </div>);
    };
    const navigationPaneTemplate = (item) => {
        const iconClass = getIconsForFolders(item);
        return (<div className="e-nav-pane-node" style={{ display: 'inline-flex', alignItems: 'center' }}>
        <span className={`e-icons ${iconClass}`}></span>
        <span className="folder-name" style={{ marginLeft: 8 }}>{item.name}</span>
      </div>);
    };
    return (<div>
      <div className="control-section">
        <div className="sample-container">
          <FileManagerComponent id="template_filemanager" ref={fmRef} ajaxSettings={{
            url: `${hostUrl}api/FileManager/FileOperations`,
            uploadUrl: `${hostUrl}api/FileManager/Upload`,
            downloadUrl: `${hostUrl}api/FileManager/Download`,
            getImageUrl: `${hostUrl}api/FileManager/GetImage`
        }} cssClass="e-fm-template-sample" height="600px" detailsViewSettings={detailsViewSettings} largeIconsTemplate={largeIconsTemplate} navigationPaneTemplate={navigationPaneTemplate} menuOpen={menuOpen} fileLoad={fileLoad}>
            <Inject services={[NavigationPane, DetailsView, Toolbar]}/>
          </FileManagerComponent>
        </div>
      </div>


    </div>);
};
export default Template;

const root = createRoot(document.getElementById('sample'));
root.render(<Template />);
